import{_ as o,o as a,c as t,a2 as n}from"./chunks/framework.C1fFCwpm.js";const p=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":1793847995000}'),i={name:"guide/overview.md"};function r(s,e,d,c,l,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><h2 id="how-the-api-is-organised" tabindex="-1">How the API is organised <a class="header-anchor" href="#how-the-api-is-organised" aria-label="Permalink to &quot;How the API is organised&quot;">​</a></h2><p>The surface is taken from a <strong>live in-game <code>_G</code> dump</strong> (108 names, hash <code>19601d21</code>, identical on PC and Android). It splits into:</p><ul><li><strong><a href="/CGT_Docs_API/api/globals">Global functions</a></strong> - registered directly in the script globals (e.g. <code>GetTile</code>, <code>GetWorld</code>).</li><li><strong>Namespaces</strong> - tables of methods called as <code>Namespace.method(...)</code>: <a href="/CGT_Docs_API/api/client"><code>Client</code></a>, <a href="/CGT_Docs_API/api/entities"><code>Entities</code></a>, <a href="/CGT_Docs_API/api/input"><code>Input</code></a>, <a href="/CGT_Docs_API/api/proton"><code>Proton</code></a>, <a href="/CGT_Docs_API/api/render"><code>Render</code></a>, <a href="/CGT_Docs_API/api/script"><code>Script</code></a>, <a href="/CGT_Docs_API/api/ui"><code>UI</code></a>.</li></ul><p>A name&#39;s badge/signature is attached when it was individually reverse-engineered; some namespace methods share a handler and are listed name-only (confirmed by the dump, signature not individually recovered).</p><h2 id="how-to-read-a-function-entry" tabindex="-1">How to read a function entry <a class="header-anchor" href="#how-to-read-a-function-entry" aria-label="Permalink to &quot;How to read a function entry&quot;">​</a></h2><p>Each function shows a Lua-style signature, an inferred description, the address it was recovered from, a parameter table and (when it returns a table) its field list:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GetTile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(integer, integer) → table</span></span></code></pre></div><ul><li><strong>Parameters</strong> are listed by <strong>position</strong> and <strong>type</strong>. Argument <em>names</em> are not stored in the binary, so positions are shown as <code>#1</code>, <code>#2</code>, … with the recovered type. <code>type?</code> (or <em>Required: no</em>) marks an optional argument recovered from <code>luaL_opt*</code>.</li><li>A type shown as <code>integer | string</code> means the function accepts <strong>either</strong> at that position (an overload recovered from the binary).</li><li><strong>Variadic</strong> means the function reads a variable number of arguments (<code>lua_gettop</code>); only the arguments it validates up front are listed.</li><li><strong>Returns <code>table</code></strong> links to the matching <a href="/CGT_Docs_API/structs">struct</a> when the field shape is a named one.</li></ul><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li><strong>Types</strong> map to Lua: <code>integer</code> and <code>number</code> are both Lua numbers; <code>string</code>, <code>boolean</code>, <code>table</code>, <code>nil</code> as usual; <code>any</code> is an unconstrained value.</li><li><strong>Coordinates</strong>: world/tile functions take integer tile coordinates; render/screen functions take <code>number</code> pixel coordinates. Conversions depend on the engine tile size.</li><li>Generic method names (<code>Get</code>, <code>Set</code>, <code>Create</code>, <code>Clear</code>, ...) appear in several namespaces (<a href="/CGT_Docs_API/api/entities"><code>Entities</code></a>, <a href="/CGT_Docs_API/api/proton"><code>Proton</code></a>, <a href="/CGT_Docs_API/api/ui"><code>UI</code></a>); they are distinct functions per namespace, so they are listed name-only rather than sharing one reverse-engineered signature.</li></ul><h2 id="what-is-not-here" tabindex="-1">What is <em>not</em> here <a class="header-anchor" href="#what-is-not-here" aria-label="Permalink to &quot;What is *not* here&quot;">​</a></h2><ul><li><code>MakeRequest</code> is <strong>not</strong> part of the stock V1.50 surface (it is absent from the <code>_G</code> dump). The <strong>mydll-patched</strong> build adds its own - see <a href="/CGT_Docs_API/boolua/functions#makerequest">BooLua</a>.</li><li>Lua standard-library tables (<code>math</code>, <code>string</code>, <code>table</code>, ...) are available to scripts but excluded from the API fingerprint; <code>lock</code>/<code>sleep</code>/<code>unlock</code> are engine-internal (<a href="/CGT_Docs_API/internal">Internal environment</a>).</li><li>The runtime <code>_G</code> fingerprint is <strong>108 names</strong> (hash <code>19601d21</code>), identical on PC and Android - this site documents all of them.</li></ul>',13)])])}const g=o(i,[["render",r]]);export{p as __pageData,g as default};
